   [179]={next_id=180, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我会替你去做你想要做的事情，不论是阻止维里塔的阴谋，还是保护玩家名字，我都会替你完成。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [180]={next_id=181, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="<color=silver>所以，好好睡一觉吧，我亲爱的孩子。\n我保证，等你醒来，你会获得完全的自由和渴望得到的幸福。</color>", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT307_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, page_show_effect={ 0.20, 0, 5, 0, 0.00, 0.00, 0.00, 0.00, 873.00, 341.00, 1.00, {}, {}, 1.00}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
