   [231]={next_id=232, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听到深海的疑问，丽娜点头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_407.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [232]={next_id=233, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="令她平安只是我的初衷，我更愿意看到她成长，既然她喜欢那个男孩子，那我就会想办法成全她，顺便还能检测一番他的真心。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_407.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
